"""Coverage for the Hebrew-mark handling in scripts/lib/typography_fixes.py and
the apostrophe classifier it shares with scripts/lib/style_metrics_core.py.

Pins three defects found by a live `/academic-writer:write` run on a Hebrew
seminar paper (plugin 0.7.6), plus one regression that run exposed in 0.7.6
itself:

  1. `fix_quotes`' span regex paired the geresh in `ר'` with the geresh in
     `בעמ'` and rewrote the Hebrew between them — `ר' יוסף בעמ' 12` came back
     as `ר" יוסף בעמ" 12`, turning "Rabbi" into an acronym mark. Four writers
     on one article hit this independently and rejected the whole diff by hand.
  2. The same pairing destroyed English contractions: `don't break the
     writer's text` -> `don“t break the writer”s text`. Pre-existing, and it
     affects any English article with two contractions on a line.
  3. Two Hebrew transliterations on one line (ג'ון ... אתרח'סיס) paired into a
     false quoted span in the 0.7.6 tokenizer. Each worked alone, which is why
     the corpus check passed and it shipped.
"""

from __future__ import annotations

import json
import os
import subprocess
import sys
import unittest

ROOT_DIR = os.path.dirname(os.path.dirname(os.path.abspath(__file__)))
LIB_DIR = os.path.join(ROOT_DIR, "src", "scripts", "lib")
SCRIPT = os.path.join(ROOT_DIR, "src", "scripts", "detect-ai-typography.py")
if LIB_DIR not in sys.path:
    sys.path.insert(0, LIB_DIR)

from style_metrics_core import tokenize_words  # noqa: E402

GERESH = "׳"
GERSHAYIM = "״"


def fix(text: str) -> str:
    out = subprocess.run(
        [sys.executable, SCRIPT, "--fix-and-output", "--json"],
        input=text, capture_output=True, text=True, check=True,
    )
    return json.loads(out.stdout).get("fixed_text", "")


class HebrewMarksSurviveTypographyFixTest(unittest.TestCase):
    def test_geresh_is_not_paired_into_a_quoted_span(self):
        got = fix("כך כתב ר' יוסף בעמ' 12.")
        self.assertNotIn('ר"', got)
        self.assertIn("ר" + GERESH, got)
        self.assertIn("בעמ" + GERESH, got)

    def test_ascii_gershayim_folds_to_the_real_character(self):
        got = fix('וכן ז"ל, והשוו לרמב"ם.')
        self.assertIn("ז" + GERSHAYIM, got)
        self.assertIn("לרמב" + GERSHAYIM + "ם", got)

    def test_two_transliterations_on_one_line(self):
        got = fix("ג'ון כתב על אתרח'סיס.")
        self.assertIn("ג" + GERESH + "ון", got)
        self.assertIn("אתרח" + GERESH + "סיס", got)
        self.assertNotIn('"', got)

    def test_real_hebrew_quoted_phrase_is_left_alone(self):
        self.assertEqual(fix('הוא אמר "שלום רב" ואז.'), 'הוא אמר "שלום רב" ואז.')

    def test_english_contractions_are_not_quote_delimiters(self):
        self.assertEqual(
            fix("don't break the writer's text"), "don't break the writer's text"
        )

    def test_english_quoted_phrase_still_gets_curly_quotes(self):
        self.assertEqual(fix("He said 'hello' loudly."), "He said “hello” loudly.")


class TokenizerApostropheTest(unittest.TestCase):
    """The 0.7.6 candidate-opener rule paired two transliterations on one line.
    Each passed alone, so both the unit tests and the corpus check missed it —
    the corpus happens never to put two on one line."""

    def test_two_transliterations_stay_whole(self):
        self.assertEqual(
            tokenize_words("ג'ון כתב על אתרח'סיס"),
            ["ג" + GERESH + "ון", "כתב", "על", "אתרח" + GERESH + "סיס"],
        )

    def test_prefix_glued_title_still_splits_correctly(self):
        self.assertIn("והקבלה", tokenize_words("ו'הכתב והקבלה' אשר"))
        self.assertNotIn("והקבלה" + GERESH, tokenize_words("ו'הכתב והקבלה' אשר"))

    def test_prefix_set_is_closed(self):
        """ג and ד are not Hebrew prefixes, so a single-letter stem before a
        geresh is a transliteration, not a quoted title."""
        self.assertIn("ד" + GERESH + "אלמבר", tokenize_words("ד'אלמבר כתב"))

    def test_english_apostrophes_untouched(self):
        self.assertEqual(
            tokenize_words("don't split the writer's text"),
            ["don't", "split", "the", "writer's", "text"],
        )

    def test_closing_quote_still_recognised(self):
        self.assertEqual(tokenize_words("'חכמת ישראל'"), ["חכמת", "ישראל"])


if __name__ == "__main__":
    unittest.main()
